122	    private static final class CycleDetector {
123	        private final DirectedGraph graph;
124	        private final int[] indegree;
125	        private final Queue<Integer> zeroIndegreeVertices;
126	        private int visitedCount;
127	
128	        private CycleDetector(DirectedGraph graph) {
129	            this.graph = graph;
130	            this.indegree = graph.indegreeSnapshot();
131	            this.zeroIndegreeVertices = collectZeroIndegreeVertices(indegree);
132	        }
133	
134	        private boolean hasCycle() {
135	            while (!zeroIndegreeVertices.isEmpty()) {
136	                processNextVertex();
137	            }
138	            return visitedCount != graph.vertexCount();
139	        }
140	
141	        private void processNextVertex() {
142	            int vertex = zeroIndegreeVertices.poll();
143	            visitedCount++;
144	
145	            for (int neighbor : graph.neighborsOf(vertex)) {
146	                decrementIndegree(neighbor);
147	            }
148	        }
149	
150	        private void decrementIndegree(int vertex) {
151	            indegree[vertex]--;
152	            if (indegree[vertex] == 0) {
153	                zeroIndegreeVertices.add(vertex);
154	            }
155	        }
