157	        private static Queue<Integer> collectZeroIndegreeVertices(int[] indegree) {
158	            Queue<Integer> queue = new ArrayDeque<>();
159	            for (int vertex = 0; vertex < indegree.length; vertex++) {
160	                if (indegree[vertex] == 0) {
161	                    queue.add(vertex);
162	                }
163	            }
164	            return queue;
165	        }
166	    }
